INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bb555567-5d26-48a3-a447-a20be8369197', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$121. óra: Kördiagram$q$, $q$Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "5c748510-953f-43b8-8ea9-16f20df5adba", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "187c9ca3-2501-4f0e-9673-c0c31d841299", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "08af3269-c591-4d04-93e5-86b218d47550", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "0a587b7e-a57a-4d9e-8133-0a88fa4d5322", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "1ddedc48-94eb-401c-86a7-f3819b601f4f", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "28cef1fd-b474-4a7e-8bb1-49725207761b", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "959cb1df-c50e-43af-83c0-273dc31deb40", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "baaba2d4-d65a-4be1-a3f2-3396d243eeda", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "83feca0d-cf63-4565-9887-f1a9950f7c15", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "0bcf6edc-616c-4813-99d5-87eab72d4058", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "7b180655-57fd-4acb-9c5c-d6a6edc141ad", "text": "Igaz", "isCorrect": true}, {"id": "936080c7-6adb-4448-af87-dcc7f1d8ab2d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "67183db8-2175-43e1-84dd-e9537e202231", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "3bc1b638-8d38-4e81-883b-44f14fc63a33", "text": "Igaz", "isCorrect": true}, {"id": "ebaa715a-2671-41a7-99e5-d653164d9de4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('301b2cf7-5b0f-4915-b066-d1faf9800dce', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$122. óra: Adatok ábrázolása, átlag$q$, $q$Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "fd1f99bf-10ad-46c8-9133-9aab4ec8ba12", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "621c63c9-447d-4f5e-8fdf-72c24170fb1d", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "3c047d03-5d09-4d94-9108-79e970f36f2f", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "9518d363-1e00-428e-9146-9833d9979f83", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "15600fe0-df14-41d7-9871-bd6a1fa7b458", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "50b40d74-2139-4a55-8e54-c3ece3d048ee", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "8fe3d6e4-77c8-4770-9edd-f850ded0e074", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "b02e7349-a025-499d-8d97-78a5f224ff13", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "5d82e7dd-c3a7-4d1b-bef1-ef51b134238f", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "16b8f717-bf11-4d06-be8e-3398df344c98", "text": "Igaz", "isCorrect": true}, {"id": "45370e49-adfe-4cb8-9563-b84915f6ffd6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aaf16243-0a77-4de1-9e92-8392d70c8654", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "b9549953-b0bc-45fe-a9a4-326a180b7e15", "text": "Igaz", "isCorrect": true}, {"id": "5dacf559-1378-48de-8693-98eb4e3da298", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7ab89079-a692-4701-8435-52c6f7cd3521", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8daa2f74-fe2d-4ce4-825e-0324fc261a76', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$123. óra: Dobáljunk kockákat!$q$, $q$Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "4375105f-b8da-4996-9481-d6c4dc907626", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "65fb608e-4b54-4e20-9f20-d1c4485d0032", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "7e1deb50-dfe9-4a55-a9d8-cb34a24cac7f", "text": "1 a 2-ből", "isCorrect": false}, {"id": "5fc72bd4-d04d-4774-8aa4-f757fb6a0280", "text": "100%", "isCorrect": false}, {"id": "c8a56056-d89d-45c7-a216-4b6f6921e58e", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "ad760b01-73b8-41fc-93a1-fca3c07358eb", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "19fb9158-91b2-497d-8772-2586e48bfba6", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "c58ea082-fe0a-499e-bcdb-c03a26b9e394", "text": "1/6", "isCorrect": false}, {"id": "434cbbab-406e-4425-94a9-cd9ae75cc8e7", "text": "2/6", "isCorrect": false}, {"id": "151d4f5b-10f4-42ee-9e05-8cd06cfefd5e", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "cc90cdab-d4ed-48d7-baad-394c68e35160", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "abb2df7b-1d12-4bcb-84ae-97c7fc344078", "text": "Igaz", "isCorrect": true}, {"id": "a42ad0dd-3958-4a74-bf05-1caafdc4e3a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7ffc114d-7d71-4eee-9130-e046292158fb", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "d9fe9567-c4b0-48b8-aed1-3adbb8c2c4aa", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "35a41602-1e68-4954-bb33-c4b57d5ed4b0", "text": "Biztos esemény", "isCorrect": false}, {"id": "730f5748-24cb-46aa-a1ba-10ec15b73346", "text": "Lehetséges", "isCorrect": false}, {"id": "95b1353c-aacf-464d-a323-5ee4b7acf79f", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "ba09ebc5-6303-4626-9a66-1c622ab1dd97", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "2df06ae3-f43b-4900-91b0-7b046ffc080f", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "49e9c6fe-6310-4035-bb05-209bdddc01e7", "text": "Lehetetlen", "isCorrect": false}, {"id": "40b42d8b-7be9-4b75-b0ec-991356c9574c", "text": "Kétes", "isCorrect": false}, {"id": "d3b5bf9e-fbaa-4974-baac-58020e6d819f", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "59227be9-5608-41b1-af09-5afc55bbcb6e", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "3dc687b1-5a3d-45f1-9fee-599646b57502", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "7dfce062-f864-4163-a554-377a7b6e83c9", "text": "Igaz", "isCorrect": true}, {"id": "13c055f6-13f2-466f-b865-c934bce319c6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9d76657a-879e-4f8a-8caa-4e940a9f2b11', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$124. óra: Dobáljunk pénzérmét!$q$, $q$Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "76354c60-902b-4832-a098-a27cbabb3f92", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "c1e5d0b0-73cd-45f2-abee-acfb67a962b8", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "9aadde1f-60bf-4cb9-9b71-b9d6e24e6f2c", "text": "1/4", "isCorrect": false}, {"id": "1382f71b-9ee6-4b9f-8767-5a3c046947dc", "text": "100%", "isCorrect": false}, {"id": "03d9073e-91b0-432a-90c8-9c7e1ffb2086", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "b8987c62-6946-4696-a647-8691dcfe7110", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "6a214ae3-7e36-4eca-8185-a0f104bb260e", "text": "Igaz", "isCorrect": true}, {"id": "5a6a2403-03f4-47d3-81e7-5f81b7d6e05a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4a697c2-f901-4105-b9d0-c5d57c02497f", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "00d177af-d5f9-4499-b5e0-c236032eb1b0", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "657b297c-1c55-4af1-b650-3ca0192d0309", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "0d7c6c2f-fd09-4984-b170-8bdd3982ef89", "text": "Igaz", "isCorrect": true}, {"id": "04b8eb4a-18e5-4ff0-bfd6-28262db29625", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c5661d03-4ff7-4a90-bb08-640e9f0f723c", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "d925f78f-7afb-46a5-be07-0b5a9a571edb", "text": "Igaz", "isCorrect": true}, {"id": "822ed198-ab3e-4af8-ab2b-e0068a3b6aba", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "16ef7c3d-cd1b-4354-8246-2d3ee73b098c", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "8c272028-ac7a-4c0b-a57a-2b95f207e82e", "text": "Igaz", "isCorrect": true}, {"id": "b731f598-8423-4613-9a2e-e383e7830139", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7f6d30b4-f55d-4b8e-8e0b-0313ea797083', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$125. óra: Összefoglalás$q$, $q$Statisztikai és valószínűségi ismeretek összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "7d4ab74f-7cb7-455a-a749-4fcef334505c", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "876d4418-1a5b-4698-ba68-93a4ba10364f", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "267c8d3b-d698-4a43-a4f9-1564c18c97f6", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a06334fd-c7f2-44b9-b9ab-3e8c2a87420f", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "2bbfd366-17f4-48f5-8d11-c93e5dd9aef0", "text": "Igaz", "isCorrect": true}, {"id": "3a5de57b-dc8c-4a80-b91d-a6eb9f11a1be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5fb2b05c-871d-4483-b4d7-53c188c51707", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "d92323bb-e1ac-4446-a407-1341a700267f", "text": "Igaz", "isCorrect": true}, {"id": "141af9fe-fc13-4fc4-9ab6-219e92163e6c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9e22a534-f322-4b87-bfed-7b8d8a19e702", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "29c38f5b-6b97-4a07-9350-c69847f16201", "text": "Vonaldiagram", "isCorrect": true}, {"id": "0663f330-97d7-46a4-94b7-7fe45678370c", "text": "Kördiagram", "isCorrect": false}, {"id": "dc8d8aca-e50e-4b03-954d-d1068199de6e", "text": "Pontdiagram", "isCorrect": false}, {"id": "1469d2c7-b6c1-41e0-94fb-cff0c90ed13a", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "bd3acc65-ecb3-4061-a347-9c28c5b416c5", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0f998e20-6f0b-4097-9d69-50508f0ccb31', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$126. óra: Számonkérés$q$, $q$Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "36b04576-a102-47ab-9423-0d3e3f84a3d0", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "bdce5a40-a20d-4fdc-8600-9a1bab5b2583", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "62d4c1cd-991d-4399-9529-89a929c4bfe1", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "fd87e889-b0c5-4aec-bc80-3528c27377cf", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "c1dbed51-a40d-49e2-b65b-65f5106f769e", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "5be5de2a-e61d-4c7c-af54-623faf76ce88", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "a30ae242-0846-4a4a-beb7-ca23d0abe058", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "87107030-2b3e-4bef-893f-8b6eca2d34a7", "text": "Biztos esemény", "isCorrect": false}, {"id": "521e5922-030e-45b1-8230-062c9d5c655f", "text": "Lehetséges", "isCorrect": false}, {"id": "9ffe6837-01e5-4c0f-a74b-caff645a8e55", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "f61d503b-a205-46e4-973b-0d889fd54f4f", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "26216ad4-28a4-4e8d-9290-63ed9f0d1508", "text": "Biztos esemény", "isCorrect": true}, {"id": "d0f5ad7a-abce-48dd-8fee-adf87c86ee0b", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "a822290a-805e-4606-b999-f95824901bd6", "text": "Ritka", "isCorrect": false}, {"id": "1b647ee1-fad0-4769-b8d1-71b2796f9a8a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cda7d528-4498-4b89-8844-9ca144b54661", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "ae45c8c1-6b9d-4aac-9dc8-fd3f7ba05bc3", "text": "Igaz", "isCorrect": true}, {"id": "4f44a180-77b7-4103-a350-2181bc6af6df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd10fff3-c232-4550-a649-1c50cfc3b3b2", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "90d1f4e2-5076-4596-b6a6-fce963594761", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "50956553-0054-4e33-9292-a19a56fa13f7", "text": "Igaz", "isCorrect": true}, {"id": "359deccc-6aa3-48c8-abaa-84c1dd875d3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a838bdfe-eb10-4a65-8a30-638bd8ed5124', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$127. óra: A számonkérés értékelése$q$, $q$A statisztikai feladatok és projektmunkák megbeszélése, értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "68f4287d-f15c-48da-b830-b8d963fa7469", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "cae5b401-3217-47de-9027-f7619662cc92", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "aaaec873-2711-4669-b66d-904ac1dbe55b", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "64e2db3a-45ec-4f16-8b95-0d090f2eec35", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "844a303d-e061-4a31-8a6d-5690634fe010", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "dcadad34-7e3c-4fc5-b260-6c544386a9a1", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "acad53f2-8ffe-4f72-8518-57a146aca620", "text": "Igaz", "isCorrect": true}, {"id": "dfbd05d5-7186-455c-bd27-da161668cb2a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ad2a5e3c-95b6-4225-b08e-9dd0c4f05a9f", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "4271b343-5e42-4b52-90fa-b99ee29a7d6f", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "cb2ee091-4bfd-40c1-877c-d51716e51e84", "text": "Igaz", "isCorrect": true}, {"id": "dba23d13-0f3e-4a65-81bb-884f01b59bf2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "259de21f-ec31-415e-9727-4000b0d98bb6", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "8d27e726-4ff2-4e1f-beb5-4d0652c7df0c", "text": "Igaz", "isCorrect": true}, {"id": "2d166be6-cdbd-4daf-b918-fd22ed14831d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ee9fe5fa-f95d-4e69-bea5-094f0205df48", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "97728d1a-3afc-4e39-b185-c804a2343479", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "88b8f994-d45a-4cf2-aa07-036fe31b75a2", "text": "Igaz", "isCorrect": true}, {"id": "971a8392-7411-47fb-b4bf-452764551b98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b494bf5b-599a-4923-a88d-1007ec4b2243', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$128. óra: Mindennapi pénzügyeink I.$q$, $q$Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Mindennapi pénzügyeink$q$, $q$[{"id": "4586a565-c064-4c14-a6f1-17953b8e5544", "text": "Mit jelent a banki megtakarítás (betét) után járó 'kamat'?", "type": "multiple-choice", "options": [{"id": "4e9185eb-8ddb-4770-a650-23b8d4dde4ee", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "845fcbe0-aab3-41ab-a93d-765e59323541", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "d8c334ca-324e-4f24-ba0c-ad8999d8266b", "text": "A büntetés", "isCorrect": false}, {"id": "ec04e90f-6df3-45c4-a333-f248ec0471c2", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "c0360039-1c3a-4efa-bc81-8876fa400017", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "5cd5e039-398b-42b1-9d82-aaa49d0ddb0f", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "1ad61333-caaf-41eb-a651-6adc1a9fb7cb", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "9eed6bca-ed1c-4265-a2b6-fe3640810929", "text": "Igaz", "isCorrect": true}, {"id": "d17d7c50-0108-450e-8cea-89d40f171fbb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b16e36e3-2260-4c52-b6ae-2138c03314ef", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "5d223490-8b06-43ee-b646-9a7c2c9a0a53", "text": "Igaz", "isCorrect": true}, {"id": "69589b51-83e2-431f-be09-8da193035a82", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42a38dff-636c-4765-9e80-354b90d50f55", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "2a01324a-fefb-42e9-9a8d-ae3132564e9b", "text": "Igaz", "isCorrect": true}, {"id": "3ce56a8e-efde-4e8f-a919-ae5c5bd2ad3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64d0988f-659b-465e-ad3d-e06f14668c38", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('74798a29-1f86-4333-8993-e372fb688157', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$129. óra: Mindennapi pénzügyeink II.$q$, $q$Devizák, valutavételi és -eladási árfolyam, valutaváltás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Mindennapi pénzügyeink$q$, $q$[{"id": "4a2eed6e-54cf-4ea4-b2a4-5299a416c147", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "77cf2d93-d602-455c-9f4e-be25909e518d", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "236fb5b7-8f86-4d52-bb49-8ed0b5c7c5e1", "text": "A bankjegy színe", "isCorrect": false}, {"id": "78b7ddee-4f8b-414c-b57d-fce7f12e8e2a", "text": "A pénz súlya", "isCorrect": false}, {"id": "4e10b094-c49e-4774-b0d4-ab7130f738c4", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "3f9d1e7e-99fc-4a5f-8eed-c854582252ef", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "01ddded8-21b1-4c88-8eac-6c64db3f409f", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "9a77193d-b6e4-4ecd-a425-62c46f4fb1b6", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "766a62c3-ab6a-4770-8355-6006d3ba14e3", "text": "Igaz", "isCorrect": true}, {"id": "35661640-c27e-4128-a562-9ed09e02e5c6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a476a61c-fa85-4a1d-bee4-8e5aaca126f7", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "e486ea05-c0bd-4163-a65b-1ee295cd2b01", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "86fdb5eb-be48-4396-910b-a22b1e4e891a", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "b7fb7236-e10a-430e-bf82-f4b7ea7174cd", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "488c42e4-9562-4bcd-8dbd-95d695b52814", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "7eb1b9f2-713f-4414-b1be-a002ac9a1eb2", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "855518c7-732d-419b-80ef-abbadbf815da", "text": "Igaz", "isCorrect": true}, {"id": "8623bdb4-e3f9-4134-941e-0d17fd61a2c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "85758c14-82e2-4fe0-9494-99aad8629b5e", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('67209754-81ff-47f8-9394-aacf052a8e13', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "0e26e0fc-649a-4bc6-aaec-bbe0e94188ae", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e863eb61-d16a-44d1-ae2d-7cea8d5f94a8", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "2056fa61-26ef-407b-9904-0cba122e5e0c", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "441d9771-4c71-4103-a0e3-1dedd852abcd", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "cfd717b4-4a53-42af-bb36-e1b02f17009f", "text": "Igaz", "isCorrect": true}, {"id": "0a473fd4-03cb-4175-93d8-53d147ce5306", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "19367e57-3d18-4413-9cad-70fe76b83983", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "387b7d6d-b50f-4f14-8f63-253da30b8bbd", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "c8960a6a-c2b9-4dfd-b947-73f6f2e5f15a", "text": "-4", "isCorrect": true}, {"id": "49a1b10b-f1da-43b4-b149-7a8ede414abc", "text": "-12", "isCorrect": false}, {"id": "84326f79-7550-457c-b286-29b1ef9b75f7", "text": "Egyenlők", "isCorrect": false}, {"id": "b211203f-695c-47f6-99b6-fade6d7f2f24", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "31d2a4a6-ad0d-405f-8da8-0b0af276c7c6", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;